using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System.IO;
using System.Threading.Tasks;

namespace FileExportService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ExportController : ControllerBase
    {
        private readonly string _exportBasePath;
        private readonly string _stagingPath;

        public ExportController(IConfiguration config)
        {
            _exportBasePath = config.GetValue<string>("Export:BasePath") ?? "/var/exports";
            _stagingPath = config.GetValue<string>("Export:StagingPath") ?? "/tmp/staging";
        }

        /// <summary>
        /// Creates an export job that writes user data to a file.
        /// The caller specifies a relative filename for the export.
        /// </summary>
        [HttpPost("create")]
        [Authorize(Policy = "ExportUser")]
        public async Task<IActionResult> CreateExport([FromBody] ExportRequest request)
        {
            if (string.IsNullOrWhiteSpace(request.Filename))
                return BadRequest("Filename is required");

            // Sanitize: strip directory traversal sequences
            var sanitized = request.Filename.Replace("..", "").Replace("/", "").Replace("\\", "");

            // Stage the export in a temp location first
            var stagingFile = Path.Combine(_stagingPath, sanitized);

            // Write export content to staging
            await System.IO.File.WriteAllTextAsync(stagingFile, request.Content ?? "export data placeholder");

            // Move from staging to final export path
            // NOTE: If stagingFile is a symlink, this follows it
            var finalPath = Path.Combine(_exportBasePath, sanitized);

            // Check if staging file exists before copy
            if (!System.IO.File.Exists(stagingFile))
                return StatusCode(500, "Staging file not found");

            // Copy staged file to export directory
            System.IO.File.Copy(stagingFile, finalPath, overwrite: true);

            // Cleanup staging
            System.IO.File.Delete(stagingFile);

            return Ok(new { path = finalPath, status = "exported" });
        }

        /// <summary>
        /// Retrieves a previously exported file by name.
        /// </summary>
        [HttpGet("download/{filename}")]
        [Authorize(Policy = "ExportUser")]
        public IActionResult DownloadExport(string filename)
        {
            var sanitized = filename.Replace("..", "").Replace("/", "").Replace("\\", "");
            var filePath = Path.Combine(_exportBasePath, sanitized);

            if (!System.IO.File.Exists(filePath))
                return NotFound();

            // WARNING: If filePath is a symlink pointing elsewhere, this follows it
            var stream = System.IO.File.OpenRead(filePath);
            return File(stream, "application/octet-stream", sanitized);
        }

        /// <summary>
        /// Prepares staging directory - creates symlink-based structure for performance.
        /// Called during initialization or by admin.
        /// </summary>
        [HttpPost("prepare-staging")]
        [Authorize(Policy = "AdminOnly")]
        public IActionResult PrepareStagingDirectory([FromBody] StagingConfig config)
        {
            if (!Directory.Exists(_stagingPath))
                Directory.CreateDirectory(_stagingPath);

            // If a link target is specified, create a symlink in staging
            // This is used for shared storage mounts in clustered deployments
            if (!string.IsNullOrEmpty(config.LinkTarget))
            {
                var linkPath = Path.Combine(_stagingPath, config.LinkName ?? "shared");
                if (!System.IO.File.Exists(linkPath) && !Directory.Exists(linkPath))
                {
                    // Create symlink for shared storage
                    // On Linux: this creates actual filesystem symlinks
                    System.IO.File.CreateSymbolicLink(linkPath, config.LinkTarget);
                }
            }

            return Ok(new { staging = _stagingPath, ready = true });
        }
    }

    public class ExportRequest
    {
        public string Filename { get; set; }
        public string Content { get; set; }
    }

    public class StagingConfig
    {
        public string LinkTarget { get; set; }
        public string LinkName { get; set; }
    }
}
